import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('createCreditNote: create credit note for issued invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const creditResult = createCreditNote(issued.value, { amount: 10000, reason: 'Discount', date: '2026-01-20' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.number, 'CN-2026-0001');
  assert.equal(creditResult.value.invoiceNumber, issued.value.number);
  assert.equal(creditResult.value.customerId, 'C-002');
  assert.equal(creditResult.value.amount, 10000);
  assert.equal(creditResult.value.reason, 'Discount');
  assert.equal(creditResult.value.date, '2026-01-20');
});

test('createCreditNote: creates credit note for partially paid invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const paymentResult = recordPayment(issued.value, { amount: 30000, date: '2026-01-20' });
  assert.ok(paymentResult.ok);

  const creditResult = createCreditNote(paymentResult.value, { amount: 5000, reason: 'Adjustment', date: '2026-01-25' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.number, 'CN-2026-0001');
});

test('createCreditNote: creates credit note for paid invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const paymentResult = recordPayment(issued.value, { amount: 91960, date: '2026-01-20' });
  assert.ok(paymentResult.ok);

  const creditResult = createCreditNote(paymentResult.value, { amount: 5000, reason: 'Return', date: '2026-01-25' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.number, 'CN-2026-0001');
});

test('createCreditNote: error NOT_ISSUED for draft invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);

  const creditResult = createCreditNote(invResult.value, { amount: 10000, reason: 'Discount', date: '2026-01-20' }, []);
  assert.ok(!creditResult.ok);
  assert.equal(creditResult.error, 'NOT_ISSUED');
});

test('createCreditNote: error AMOUNT_INVALID for zero', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const creditResult = createCreditNote(issued.value, { amount: 0, reason: 'Invalid', date: '2026-01-20' }, []);
  assert.ok(!creditResult.ok);
  assert.equal(creditResult.error, 'AMOUNT_INVALID');
});

test('createCreditNote: error AMOUNT_INVALID for negative', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const creditResult = createCreditNote(issued.value, { amount: -1000, reason: 'Invalid', date: '2026-01-20' }, []);
  assert.ok(!creditResult.ok);
  assert.equal(creditResult.error, 'AMOUNT_INVALID');
});

test('createCreditNote: error AMOUNT_INVALID for non-integer', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const creditResult = createCreditNote(issued.value, { amount: 5000.5, reason: 'Invalid', date: '2026-01-20' }, []);
  assert.ok(!creditResult.ok);
  assert.equal(creditResult.error, 'AMOUNT_INVALID');
});

test('createCreditNote: error DATE_INVALID', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const creditResult = createCreditNote(issued.value, { amount: 10000, reason: 'Discount', date: '01/20/2026' }, []);
  assert.ok(!creditResult.ok);
  assert.equal(creditResult.error, 'DATE_INVALID');
});

test('createCreditNote: error CREDIT_TOO_HIGH', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Total is 91960, try to credit 100000
  const creditResult = createCreditNote(issued.value, { amount: 100000, reason: 'Too much', date: '2026-01-20' }, []);
  assert.ok(!creditResult.ok);
  assert.equal(creditResult.error, 'CREDIT_TOO_HIGH');
});

test('createCreditNote: full credit equal to invoice total', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Credit exactly the total
  const creditResult = createCreditNote(issued.value, { amount: 91960, reason: 'Full refund', date: '2026-01-20' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.amount, 91960);
});

test('createCreditNote: credit for 1 cent', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const creditResult = createCreditNote(issued.value, { amount: 1, reason: 'Minimal', date: '2026-01-20' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.amount, 1);
});

test('createCreditNote: sequential numbering', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(invResult.ok);
  const issued1 = issueInvoice(invResult.value, []);
  assert.ok(issued1.ok);

  const credit1 = createCreditNote(issued1.value, { amount: 1000, reason: 'First', date: '2026-01-20' }, []);
  assert.ok(credit1.ok);
  assert.equal(credit1.value.number, 'CN-2026-0001');

  // Create second invoice and credit
  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(inv2Result.ok);
  const issued2 = issueInvoice(inv2Result.value, [issued1.value.number]);
  assert.ok(issued2.ok);

  const credit2 = createCreditNote(issued2.value, { amount: 1000, reason: 'Second', date: '2026-02-20' }, [credit1.value.number]);
  assert.ok(credit2.ok);
  assert.equal(credit2.value.number, 'CN-2026-0002');
});

test('createCreditNote: separate counter from invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Credit note should start at 0001, not be affected by invoice number
  const creditResult = createCreditNote(issued.value, { amount: 1000, reason: 'Test', date: '2026-01-20' }, [issued.value.number]);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.number, 'CN-2026-0001');
});

test('createCreditNote: credit note number resets yearly', () => {
  const invResult1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(invResult1.ok);
  const issued1 = issueInvoice(invResult1.value, []);
  assert.ok(issued1.ok);

  const credit1 = createCreditNote(issued1.value, { amount: 1000, reason: 'First', date: '2026-01-20' }, []);
  assert.ok(credit1.ok);
  assert.equal(credit1.value.number, 'CN-2026-0001');

  // Create invoice and credit in next year
  const invResult2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2027-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(invResult2.ok);
  const issued2 = issueInvoice(invResult2.value, []);
  assert.ok(issued2.ok);

  // Counter should reset to 0001 for new year
  const credit2 = createCreditNote(issued2.value, { amount: 1000, reason: 'Next year', date: '2027-01-20' }, [credit1.value.number]);
  assert.ok(credit2.ok);
  assert.equal(credit2.value.number, 'CN-2027-0001');
});

test('createCreditNote: handles mixed existing numbers', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Existing numbers include both invoices and credit notes
  const existingNumbers = [
    'INV-2026-0001',
    'INV-2026-0002',
    'CN-2026-0001',
    'CN-2026-0002',
  ];

  const creditResult = createCreditNote(issued.value, { amount: 1000, reason: 'Test', date: '2026-01-20' }, existingNumbers);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.number, 'CN-2026-0003');
});

test('createCreditNote: large credit note number', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Simulate many existing credit notes
  const existingNumbers = Array.from({ length: 9999 }, (_, i) => `CN-2026-${String(i + 1).padStart(4, '0')}`);

  const creditResult = createCreditNote(issued.value, { amount: 1000, reason: 'Test', date: '2026-01-20' }, existingNumbers);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.number, 'CN-2026-10000');
});

test('createCreditNote: credit note with discount invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8, discountPercent: 10 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  // Total is 82764 (76000 - 7600 + 14364 VAT)
  const creditResult = createCreditNote(issued.value, { amount: 10000, reason: 'Partial refund', date: '2026-01-20' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.amount, 10000);
});

test('createCreditNote: credit note with voucher invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);

  // Import applyVoucher inline to avoid issues
  const { applyVoucher } = await import('../src/invoices.js');
  const voucherInvoice = applyVoucher(invResult.value, { code: 'SUMMER10', amount: 5000 });
  assert.ok(voucherInvoice.ok);

  const issued = issueInvoice(voucherInvoice.value, []);
  assert.ok(issued.ok);

  // Total is 86960 (91960 - 5000)
  const creditResult = createCreditNote(issued.value, { amount: 10000, reason: 'Refund', date: '2026-01-20' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.amount, 10000);
});

test('createCreditNote: reason field preserved', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const creditResult = createCreditNote(issued.value, { amount: 10000, reason: 'Damaged goods - return authorization #RMA-001', date: '2026-01-20' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.reason, 'Damaged goods - return authorization #RMA-001');
});

