    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });
  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const paymentResult = recordPayment(issued.value, { amount: 91960, date: '2026-01-20' });
  assert.ok(paymentResult.ok);

  const creditResult = createCreditNote(paymentResult.value, { amount: 5000, reason: 'Return', date: '2026-01-25' }, []);
  assert.ok(creditResult.ok);
  assert.equal(creditResult.value.number, 'CN-2026-0001');
});

