test('createCreditNote: sequential numbering', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(invResult.ok);
  const issued1 = issueInvoice(invResult.value, []);
  assert.ok(issued1.ok);

  const credit1 = createCreditNote(issued1.value, { amount: 1000, reason: 'First', date: '2026-01-20' }, []);
  assert.ok(credit1.ok);
  assert.equal(credit1.value.number, 'CN-2026-0001');

  // Create second invoice and credit
  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(inv2Result.ok);
  const issued2 = issueInvoice(inv2Result.value, [issued1.value.number]);
  assert.ok(issued2.ok);

  const credit2 = createCreditNote(issued2.value, { amount: 1000, reason: 'Second', date: '2026-02-20' }, [credit1.value.number]);
  assert.ok(credit2.ok);
  assert.equal(credit2.value.number, 'CN-2026-0002');
});

